 public const string BuildLabel="0.1.0-alpha.1 / Standalone";
 public bool ReadyForCommands{get{return Ready()&&!Automation.Owned&&!ShuttleReturnActive();}}
 float chargeTimer; bool powered; double fuel,oxidizer,ec,ecMax,mass,thrust;
 bool ownsSAS; VesselAutopilot.AutopilotMode requestedMode;
