 public string InclinationText="0";public bool AutoStage=true,AutoWarp=true;public int Page=0;Vector2 scroll;float backendTimer;
 public GroundworksFlightTools Tools;public int ToolPage;public double TerrainSlope=-1;public int RigidSupports,ExtendedSupports;bool editingField;float terrainTimer;string observedEvent="";string profileName="My flight",siteName="Landing site",apsisTarget="40";int selectedProfile,selectedSite;
 public void Awake(){Instance=this;Tools=new GroundworksFlightTools(System.IO.Path.Combine(KSPUtil.ApplicationRootPath,"GameData/GroundworksFlightComputer/PluginData"));}
 public void Update(){
  window.x=Mathf.Clamp(window.x,0,Mathf.Max(0,Screen.width-window.width));window.y=Mathf.Clamp(window.y,0,Mathf.Max(0,Screen.height-80));
  if(FlightGlobals.ActiveVessel!=controlled)Bind(FlightGlobals.ActiveVessel);
