  if(ownsSAS&&controlled!=null&&(!controlled.Autopilot.Enabled||controlled.Autopilot.Mode!=requestedMode)){ownsSAS=false;if(!Armed)Status="MANUAL SAS";}
  if(!Visible||Page==2){editingField=false;InputLockManager.RemoveControlLock("GWComputerTarget");}
