  backendTimer+=Time.unscaledDeltaTime;if(backendTimer>.25f){backendTimer=0;bool wasAutomatic=Automation.Owned;Automation.Refresh();if(wasAutomatic||Automation.Owned)Status=Automation.Message;if(ShuttleReturnActive()){var bridge=ShuttleReturnModule();Status=(string)bridge.Fields["recoveryStatus"].GetValue(bridge);}}
  if(Automation.Owned&&controlled!=null&&!controlled.packed&&!controlled.IsControllable)Stop("CONTROL LOST - AUTOPILOT ABORTED");
  if(controlled!=null&&Tools!=null){string key=Automation.Task+"|"+Automation.Phase+"|"+(Automation.Owned?"":Status);if(key!=observedEvent){observedEvent=key;Tools.Record(Planetarium.GetUniversalTime(),controlled.mainBody.bodyName,controlled.vesselName,Automation.Owned?Automation.Task+" / "+Automation.Phase:Status);}}
