 void Bind(Vessel next){Stop("MANUAL");if(controlled!=null)controlled.OnFlyByWire-=Fly;controlled=next;Automation.Bind(next);if(controlled!=null)controlled.OnFlyByWire+=Fly;chargeTimer=1;powered=false;}
 public void FixedUpdate(){
  if(controlled==null)return;
  chargeTimer+=TimeWarp.fixedDeltaTime;if(chargeTimer<.25f)return;float elapsed=chargeTimer;chargeTimer=0;
  fuel=oxidizer=ec=ecMax=0;thrust=0;activeEngines=throttleableEngines=landingGear=0;availableThrust=0;inventory.Clear();
  foreach(var p in controlled.parts){foreach(PartResource r in p.Resources){double[] stock;if(!inventory.TryGetValue(r.resourceName,out stock)){stock=new double[2];inventory.Add(r.resourceName,stock);}stock[0]+=r.amount;stock[1]+=r.maxAmount;if(r.resourceName=="LiquidFuel")fuel+=r.amount;if(r.resourceName=="Oxidizer")oxidizer+=r.amount;if(r.resourceName=="ElectricCharge"){ec+=r.amount;ecMax+=r.maxAmount;}}foreach(var e in p.FindModulesImplementing<ModuleEngines>())if(e.EngineIgnited){thrust+=e.finalThrust;if(!e.flameout){activeEngines++;if(!e.throttleLocked)throttleableEngines++;double vacuum=e.atmosphereCurve.Evaluate(0);availableThrust+=e.maxThrust*e.thrustPercentage*.01*(vacuum>0?e.atmosphereCurve.Evaluate((float)(controlled.staticPressurekPa/101.325))/vacuum:1);}}if(p.Modules.Cast<PartModule>().Any(m=>m.moduleName=="ModuleWheelDeployment"||m.moduleName=="ModuleLandingLeg"))landingGear++;}
  mass=controlled.GetTotalMass();powered=ec>.0001;RigidSupports=ExtendedSupports=0;foreach(var p in controlled.parts)if(IsGWStrut(p)){RigidSupports++;var m=p.FindModuleImplementing<ModuleAnimateGeneric>();if(m!=null&&m.animTime<.01)ExtendedSupports++;}
  if((Armed||ownsSAS||Automation.Owned)&&!controlled.packed&&TimeWarp.CurrentRate<=4){double need=.015*Math.Min(elapsed,.5);powered=controlled.rootPart.RequestResource("ElectricCharge",need)>=need*.99;if(!powered){Stop("NO POWER - AUTOPILOT ABORTED");}}
 }
 PartModule ShuttleReturnModule(){return controlled==null?null:controlled.parts.SelectMany(p=>p.Modules.Cast<PartModule>()).FirstOrDefault(m=>m.moduleName=="GroundworksShuttleReturn");}
 bool ShuttleReturnActive(){var module=ShuttleReturnModule();return module!=null&&module.Fields["controllerActive"]!=null&&object.Equals(module.Fields["controllerActive"].GetValue(module),true);}
 void AbortShuttleReturn(){var module=ShuttleReturnModule();if(module!=null&&ShuttleReturnActive()&&module.Events["AbortReturn"]!=null)module.Events["AbortReturn"].Invoke();}
 bool Ready(){return controlled!=null&&!controlled.packed&&TimeWarp.CurrentRate<=4&&controlled.IsControllable&&powered;}
 public bool Hold(VesselAutopilot.AutopilotMode mode){
  if(Automation.HasControl||ShuttleReturnActive()){Status="DISENGAGE AUTOMATION FIRST";return false;}
  if(!Ready()){Status="NEEDS POWER / CONTROL";return false;}
  if(!controlled.Autopilot.CanSetMode(mode)){Status="SAS MODE UNAVAILABLE";return false;}
  controlled.ActionGroups.SetGroup(KSPActionGroup.SAS,true);
  if(!controlled.Autopilot.Enable(mode)){Status="SAS MODE UNAVAILABLE";return false;}
  ownsSAS=true;requestedMode=mode;Status="SAS "+mode.ToString().ToUpperInvariant();return true;
 }
 public bool Arm(){
  if(Automation.HasControl||ShuttleReturnActive()){Status="DISENGAGE AUTOMATION FIRST";return false;}
  double km;if(!double.TryParse(TargetText,NumberStyles.Float,CultureInfo.InvariantCulture,out km)||double.IsNaN(km)||double.IsInfinity(km)||km<=0||km>1000000){Status="ENTER VALID TARGET KM";return false;}
  if(!Ready()||controlled.LandedOrSplashed){Status="ARM AFTER LIFTOFF / NEEDS CONTROL";return false;}
  TargetAltitude=km*1000;if(controlled.orbit.ApA>=TargetAltitude){Status="TARGET ALREADY REACHED";return false;}
  Armed=true;Status="APOAPSIS CUTOFF ARMED";return true;
 }
 public static bool Reached(double apoapsis,double target){return !double.IsNaN(apoapsis)&&!double.IsInfinity(apoapsis)&&apoapsis>=target;}
 public void Fly(FlightCtrlState state){
  if(Automation.Owned){Automation.Drive(state);Status=Automation.Message;return;}
  if(!Armed)return;
  if(!Ready()){state.mainThrottle=0;Stop("CONTROL LOST - CUTOFF");return;}
  if(Reached(controlled.orbit.ApA,TargetAltitude)||controlled.orbit.eccentricity>=1){state.mainThrottle=0;FlightInputHandler.state.mainThrottle=0;Armed=false;Status="TARGET REACHED - CUTOFF";}
 }
 // This assistant never raises throttle. User flies/launches; this is a one-shot limit.
 public void Stop(string reason){
  Automation.Cancel(false);
  if(Armed){FlightInputHandler.state.mainThrottle=0;if(controlled!=null)controlled.ctrlState.mainThrottle=0;}Armed=false;
  if(ownsSAS&&controlled!=null&&controlled.Autopilot.Mode==requestedMode){controlled.ActionGroups.SetGroup(KSPActionGroup.SAS,false);controlled.Autopilot.Disable();}ownsSAS=false;Status=reason;
 }
 public void AbortAll(){AbortShuttleReturn();Automation.Cancel(true);bool clean=Automation.LastAbortClean;Stop(clean?"MANUAL - AUTOPILOT STOPPED":"THROTTLE CUT - CHECK CONTROL");FlightInputHandler.state.mainThrottle=0;if(controlled!=null)controlled.ctrlState.mainThrottle=0;}
 public bool StartLaunch(){if(Automation.Owned||ShuttleReturnActive()){Status="DISENGAGE AUTOMATION FIRST";return false;}InputLockManager.RemoveControlLock("GWComputerTarget");double km,inc;if(!Ready()){Status="NEEDS CONNECTED POWER / CONTROL";return false;}if(!double.TryParse(TargetText,NumberStyles.Float,CultureInfo.InvariantCulture,out km)||!double.TryParse(InclinationText,NumberStyles.Float,CultureInfo.InvariantCulture,out inc)){Status="ENTER VALID ALTITUDE / INCLINATION";return false;}Stop("STARTING LAUNCH");bool ok=Automation.Launch(km*1000,inc,AutoStage,AutoWarp);Status=Automation.Message;return ok;}
 public bool StartLanding(bool target){editingField=false;InputLockManager.RemoveControlLock("GWComputerTarget");if(Automation.Owned||ShuttleReturnActive()){Status="DISENGAGE AUTOMATION FIRST";return false;}if(!Ready()){Status="NEEDS CONNECTED POWER / CONTROL";return false;}var winged=ShuttleReturnModule();if(winged!=null){if(target){Status="SHUTTLE PRECISION TARGETING NOT IMPLEMENTED";return false;}Stop("STARTING WINGED RETURN");winged.Events["BeginReturn"].Invoke();Status=(string)winged.Fields["recoveryStatus"].GetValue(winged);return object.Equals(winged.Fields["controllerActive"].GetValue(winged),true);}if(controlled.parts.Any(p=>p.partInfo.name.StartsWith("GWSS"))){Status="SHUTTLE RETURN MODULE REQUIRED";return false;}ExtendGWSupports();Stop("STARTING LANDING");bool ok=Automation.Land(target,AutoWarp);Status=Automation.Message;return ok;}
