 public static string StatusFor(Vessel vessel){if(Instance==null||Instance.controlled!=vessel)return "MANUAL";if(Instance.ShuttleReturnActive())return "AUTO SHUTTLE RETURN";if(Instance.Automation.Owned)return "AUTO "+Instance.Automation.Task.ToUpperInvariant();if(Instance.Armed)return "AP LIMIT "+(Instance.TargetAltitude/1000).ToString("F1")+" km";string s=Instance.Status.Replace("TARGET REACHED - CUTOFF","AP LIMIT REACHED").Replace("StabilityAssist".ToUpperInvariant(),"HOLD");return s.Length>20?s.Substring(0,20):s;}
