 string Duration(double seconds){if(double.IsNaN(seconds)||double.IsInfinity(seconds)||seconds<0)return "--";return seconds>=3600?((int)(seconds/3600))+"h "+((int)(seconds%3600/60))+"m":((int)(seconds/60))+"m "+((int)(seconds%60))+"s";}
