 string nodeDv="10",nodeDelay="60";
 bool IsGWStrut(Part p){return p.partInfo!=null&&(p.partInfo.name=="GWEX0301"||p.partInfo.name=="GWEX0302"||p.partInfo.name=="GWEX0303");}
 public int ExtendGWSupports(){if(controlled==null||controlled.packed)return 0;int count=0;foreach(var p in controlled.parts)if(IsGWStrut(p)){var m=p.FindModuleImplementing<ModuleAnimateGeneric>();if(m!=null&&m.animTime>.99){m.Toggle();count++;}}Status=count>0?"EXTENDING GW SUPPORTS":"GW SUPPORTS ALREADY EXTENDED";return count;}
 void UpdateSurfaceInfo(){TerrainSlope=-1;if(controlled==null||!controlled.mainBody.hasSolidSurface||Math.Abs(controlled.latitude)>85||controlled.radarAltitude>5000)return;try{double step=25/controlled.mainBody.Radius*180/Math.PI;double lonStep=step/Math.Cos(controlled.latitude*Math.PI/180);double lat=controlled.latitude,lon=controlled.longitude;var body=controlled.mainBody;TerrainSlope=GroundworksNavigation.Slope(body.TerrainAltitude(lat+step,lon,true),body.TerrainAltitude(lat-step,lon,true),body.TerrainAltitude(lat,lon+lonStep,true),body.TerrainAltitude(lat,lon-lonStep,true),25);}catch{TerrainSlope=-1;}}
