 void DrawTools(){
  int old=ToolPage;ToolPage=GUILayout.Toolbar(ToolPage,new[]{"ORBIT","SITES","PRESETS","LOG"});if(old!=ToolPage){GUI.FocusControl(null);scroll=Vector2.zero;}
  if(ToolPage==0){Section("CHANGE AN APSIS");GUILayout.Label("Target altitude / km");apsisTarget=Field("GWApsisTarget",apsisTarget,12);GUI.enabled=ReadyForCommands;GUILayout.BeginHorizontal();if(GUILayout.Button("Set apoapsis"))PlanApsisInput(true);if(GUILayout.Button("Set periapsis"))PlanApsisInput(false);GUILayout.EndHorizontal();if(GUILayout.Button("Circularize at apoapsis")){Automation.PlanCircularization();Status=Automation.Message;}Section("TIMED VELOCITY CHANGE");GUILayout.Label("Prograde change (m/s) / delay (seconds)");GUILayout.BeginHorizontal();nodeDv=Field("GWNodeDv",nodeDv,10);nodeDelay=Field("GWNodeDelay",nodeDelay,10);GUILayout.EndHorizontal();if(GUILayout.Button("Create prograde / retrograde node")){double dv,delay;if(double.TryParse(nodeDv,NumberStyles.Float,CultureInfo.InvariantCulture,out dv)&&double.TryParse(nodeDelay,NumberStyles.Float,CultureInfo.InvariantCulture,out delay)){Automation.PlanPrograde(dv,delay);Status=Automation.Message;}else Status="ENTER VALID NODE VALUES";}GUI.enabled=true;if(controlled.patchedConicSolver!=null&&controlled.patchedConicSolver.maneuverNodes.Count>0){var n=controlled.patchedConicSolver.maneuverNodes[0];double dv=n.GetBurnVector(controlled.orbit).magnitude;Row("Next node / countdown",dv.ToString("F1")+" m/s / "+Duration(n.UT-Planetarium.GetUniversalTime()));if(n.nextPatch!=null)Row("Projected Ap / Pe",(n.nextPatch.ApA/1000).ToString("F1")+" / "+(n.nextPatch.PeA/1000).ToString("F1")+" km");Row("Approx. burn time",availableThrust>0?(dv/(availableThrust/Math.Max(.001,mass))).ToString("F1")+" s / current mass":"Activate engine for estimate");}GUILayout.Label("Set apoapsis burns at periapsis; set periapsis burns at apoapsis. Review the projected orbit in map view. High terrain is not checked.",mutedStyle);
  }else if(ToolPage==1){Section("SURFACE BOOKMARKS");siteName=Field("GWSiteName",siteName,32);if(GUILayout.Button("Bookmark ground point below vessel")){if(BookmarkCurrentSite(siteName))selectedSite=Tools.LastSiteIndex;}if(Tools.Sites.Count>0){GUILayout.BeginHorizontal();if(GUILayout.Button("<",GUILayout.Width(35)))selectedSite--;GUILayout.Label((Mathf.Clamp(selectedSite,0,Tools.Sites.Count-1)+1)+" / "+Tools.Sites.Count);if(GUILayout.Button(">",GUILayout.Width(35)))selectedSite++;GUILayout.EndHorizontal();selectedSite=Mathf.Clamp(selectedSite,0,Tools.Sites.Count-1);var p=Tools.Sites[selectedSite];GUILayout.Label(p.Name,sectionStyle);Row("Body",p.Body);Row("Latitude / longitude",p.Latitude.ToString("F4")+" / "+p.Longitude.ToString("F4"));Row("Terrain elevation",p.Height.ToString("F0")+" m");if(p.Body==controlled.mainBody.bodyName){double distance=GroundworksNavigation.Distance(controlled.mainBody.Radius,controlled.latitude,controlled.longitude,p.Latitude,p.Longitude);Row("Surface distance",distance<1?"At bookmark":(distance/1000).ToString("F2")+" km");Row("Bearing",distance<1?"--":GroundworksNavigation.Bearing(controlled.latitude,controlled.longitude,p.Latitude,p.Longitude).ToString("F1")+" deg true");}else GUILayout.Label("Travel readouts are available on "+p.Body+".",mutedStyle);if(GUILayout.Button("Remove selected bookmark")){Tools.RemoveSite(selectedSite);selectedSite=Math.Max(0,selectedSite-1);Status="BOOKMARK REMOVED";}}else GUILayout.Label("No saved sites yet.");GUILayout.Label("Bookmarks store coordinates and provide manual navigation readouts. They do not create map markers or steer the vessel.",mutedStyle);
  }else if(ToolPage==2){Section("SAVED FLIGHT SETUPS");profileName=Field("GWProfileName",profileName,32);if(GUILayout.Button("Save current setup")){if(SaveCurrentProfile(profileName))selectedProfile=Tools.LastProfileIndex;}if(Tools.Profiles.Count>0){GUILayout.BeginHorizontal();if(GUILayout.Button("<",GUILayout.Width(35)))selectedProfile--;GUILayout.Label((Mathf.Clamp(selectedProfile,0,Tools.Profiles.Count-1)+1)+" / "+Tools.Profiles.Count);if(GUILayout.Button(">",GUILayout.Width(35)))selectedProfile++;GUILayout.EndHorizontal();selectedProfile=Mathf.Clamp(selectedProfile,0,Tools.Profiles.Count-1);var p=Tools.Profiles[selectedProfile];GUILayout.Label(p.Name,sectionStyle);Row("Body",p.Body);Row("Target / inclination",p.Altitude+" km / "+p.Inclination+" deg");GUI.enabled=!Automation.Owned;if(GUILayout.Button("Load selected setup"))LoadProfile(selectedProfile);GUI.enabled=true;}GUI.enabled=!Automation.Owned;if(GUILayout.Button("Use current-body orbit default")){TargetText=(controlled.mainBody.atmosphereDepth>0?(controlled.mainBody.atmosphereDepth+10000)/1000:20).ToString("F0",CultureInfo.InvariantCulture);InclinationText="0";Status="BODY DEFAULT LOADED / GUIDANCE REMAINS MANUAL";}GUI.enabled=true;GUILayout.Label("Loading a preset changes setup values only. It never arms or starts guidance. Presets are tied to their saved body.",mutedStyle);
  }else{Section("RECENT GUIDANCE EVENTS");if(GUILayout.Button("Export flight log")){try{Tools.Export(KSPUtil.ApplicationRootPath);Status="EXPORTED TO GROUNDWORKS-LOGS";}catch{Status="COULD NOT EXPORT FLIGHT LOG";}}foreach(var line in Tools.History.Skip(Math.Max(0,Tools.History.Count-8)).Reverse())GUILayout.Label(line,mutedStyle);GUILayout.Label("A bounded local event history, not full sampled flight telemetry.",mutedStyle);}
 }
 void PlanApsisInput(bool apoapsis){double km;if(!double.TryParse(apsisTarget,NumberStyles.Float,CultureInfo.InvariantCulture,out km)){Status="ENTER A VALID ALTITUDE";return;}Automation.PlanApsis(km*1000,apoapsis);Status=Automation.Message;}
 public void OnDestroy(){InputLockManager.RemoveControlLock("GWComputerTarget");Stop("MANUAL");if(controlled!=null)controlled.OnFlyByWire-=Fly;if(button!=null&&ApplicationLauncher.Instance!=null)ApplicationLauncher.Instance.RemoveModApplication(button);if(panelSkin!=null)Destroy(panelSkin);if(panelTexture!=null)Destroy(panelTexture);if(Instance==this)Instance=null;}
}

